function getLang(){var p;try{p=(new URLSearchParams(location.search)).get('lang');}catch(_){};if(L.indexOf(p)>=0)return p;try{var s=localStorage.getItem('digiy_lang');if(L.indexOf(s)>=0)return s;}catch(_){}return 'fr';}
var lang=getLang(),t=T[lang]||T.fr;
try{localStorage.setItem('digiy_lang',lang);}catch(_){}
document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
function apply(){
 document.querySelectorAll('[data-i18n]').forEach(function(el){var k=el.getAttribute('data-i18n');if(t[k]!=null)el.textContent=t[k];});
 document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el){var k=el.getAttribute('data-i18n-placeholder');if(t[k]!=null)el.setAttribute('placeholder',t[k]);});
 document.querySelectorAll('[data-lang-btn]').forEach(function(b){b.classList.toggle('active',b.getAttribute('data-lang-btn')===lang);b.setAttribute('aria-pressed',b.getAttribute('data-lang-btn')===lang?'true':'false');});
 document.querySelectorAll('a[data-lang-link]').forEach(function(a){try{var u=new URL(a.getAttribute('href'),location.href);u.searchParams.set('lang',lang);a.setAttribute('href',u.pathname+u.search+u.hash);}catch(_){}});
 var body=document.body,titleKey=body&&body.getAttribute('data-title-key'),descKey=body&&body.getAttribute('data-desc-key');
 if(titleKey&&t[titleKey])document.title=t[titleKey];
 if(descKey&&t[descKey]){var m=document.querySelector('meta[name="description"]');if(m)m.setAttribute('content',t[descKey]);}
}
document.querySelectorAll('[data-lang-btn]').forEach(function(b){b.addEventListener('click',function(){var x=b.getAttribute('data-lang-btn');var u=new URL(location.href);u.searchParams.set('lang',x);location.href=u.pathname+u.search+u.hash;});});
apply();
window.DIGIY_MAROC_I18N={lang:lang,t:t,apply:apply};
